import numpy as np
t=df['t'];P=df['P'];y=df['dP_dt']
Pf={'1':np.ones_like(P),'P':P,'P2':P**2,'sqP':np.sqrt(P),'1/P':1/P,'lnP':np.log(P),'P3':P**3}
Tf={'1':np.ones_like(t),'t':t,'t2':t**2,'t3':t**3}
def run(pn,tn):
    cols=[];names=[]
    for a in pn:
        for b in tn:
            cols.append(Pf[a]*Tf[b]);names.append(a+'*'+b)
    A=np.column_stack(cols)
    c,_,_,_=np.linalg.lstsq(A,y,rcond=None)
    r=y-A@c
    return np.var(r)/np.var(y), names, c
for pn in [['1','P','P2'],['1','P','P2','sqP'],['1','P','P2','1/P'],['1','P','P2','lnP'],['1','P','P2','P3'],['1','P','P2','sqP','1/P','lnP','P3']]:
    for tn in [['1','t'],['1','t','t2'],['1','t','t2','t3']]:
        e,_,_=run(pn,tn); print(pn,tn,round(e,6))

